    async def update(
        self,
        id: str,
        *,
        name: typing.Optional[str] = OMIT,
        keywords: typing.Optional[typing.Sequence[str]] = OMIT,
        match: typing.Optional[UpdateCommentAutomationsRequestMatch] = OMIT,
        exclude: typing.Optional[typing.Sequence[str]] = OMIT,
        message: typing.Optional[UpdateCommentAutomationsRequestMessage] = OMIT,
        public_replies: typing.Optional[typing.Sequence[str]] = OMIT,
        mark_done: typing.Optional[bool] = OMIT,
        follow_gate: typing.Optional[UpdateCommentAutomationsRequestFollowGate] = OMIT,
        once_per_person: typing.Optional[bool] = OMIT,
        utm: typing.Optional[UpdateCommentAutomationsRequestUtm] = OMIT,
        status: typing.Optional[UpdateCommentAutomationsRequestStatus] = OMIT,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> CommentAutomation:
        """
        The account and post cannot change. Pausing stops it at once; comments made while it is paused are never answered. Resuming starts from then.

        Parameters
        ----------
        id : str
            The comment automation's id (`cauto_`).

        name : typing.Optional[str]
            For people: "Guide on the October reel".

        keywords : typing.Optional[typing.Sequence[str]]
            Any of them triggers it, in any case and with or without accents. Empty: every comment.

        match : typing.Optional[UpdateCommentAutomationsRequestMatch]
            contains: the keyword anywhere, even inside a longer word. word (the default): as a whole word or phrase. exact: the whole comment is the keyword, give or take punctuation and spaces. Always in any case and with or without accents.

        exclude : typing.Optional[typing.Sequence[str]]
            A comment with any of these, as whole words, never triggers it.

        message : typing.Optional[UpdateCommentAutomationsRequestMessage]
            The private reply: its text, and the link behind a button.

        public_replies : typing.Optional[typing.Sequence[str]]
            Up to 5. After the private reply goes out, one is posted under the comment, picked at random, so the replies do not all read the same.

        mark_done : typing.Optional[bool]
            Mark the comment's thread done once the private reply went out.

        follow_gate : typing.Optional[UpdateCommentAutomationsRequestFollowGate]
            Instagram only. The private reply asks them to follow and reply, with a button that replies for them; their reply gets the message if they follow, or the reminder once.

        once_per_person : typing.Optional[bool]
            One message per person for this automation, however many times they comment.

        utm : typing.Optional[UpdateCommentAutomationsRequestUtm]
            UTM tags added to every address in the message, so your own analytics (Google Analytics and the like) see which network and automation brought each visitor; the Rizamo links send people to the tagged address. A tag left out takes its default: `source` the network (instagram or facebook), `medium` social, `campaign` the name as a slug ("Guide on the October reel" is guide-on-the-october-reel). An empty one adds none, and a tag already in an address stays as it is. Null: none. Changing the tags, or the name while the campaign is its slug, makes new links for the new addresses; the automation's link clicks add up across them.

        status : typing.Optional[UpdateCommentAutomationsRequestStatus]
            paused stops it at once: comments made while it is paused are never answered. active resumes it from then.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        CommentAutomation
            OK

        Examples
        --------
        import asyncio

        from rizamo import AsyncRizamo

        client = AsyncRizamo(
            api_key="YOUR_API_KEY",
        )


        async def main() -> None:
            await client.comment_automations.update(
                id="cauto_01m4h40hg0f4wa1w5cfcgpjrp3",
                status="paused",
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.update(
            id,
            name=name,
            keywords=keywords,
            match=match,
            exclude=exclude,
            message=message,
            public_replies=public_replies,
            mark_done=mark_done,
            follow_gate=follow_gate,
            once_per_person=once_per_person,
            utm=utm,
            status=status,
            request_options=request_options,
        )
        return _response.data

    async def runs(
        self,
        id: str,
        *,
        status: typing.Optional[RunsCommentAutomationsRequestStatus] = None,
        cursor: typing.Optional[str] = None,
        limit: typing.Optional[int] = None,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> AsyncPager[CommentAutomationRun, RunsCommentAutomationsResponse]:
        """
        One run per matched comment, newest first, a page at a time: pass `nextCursor` as `cursor` for the next one. A run stays when its comment is deleted, but its `threadId` may then be gone from the inbox, and a private reply not sent yet is skipped (`refused`).

        Parameters
        ----------
        id : str
            The comment automation's id (`cauto_`).

        status : typing.Optional[RunsCommentAutomationsRequestStatus]
            pending: going out within minutes. waiting: the follow gate asked and waits for their reply. sent: the message with the link went out. skipped, failed, expired: `reason` says why.

        cursor : typing.Optional[str]
            `nextCursor` from the page before.

        limit : typing.Optional[int]
            How many to return, up to 100: 50 when left out.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        AsyncPager[CommentAutomationRun, RunsCommentAutomationsResponse]
            OK

        Examples
        --------
        import asyncio

        from rizamo import AsyncRizamo

        client = AsyncRizamo(
            api_key="YOUR_API_KEY",
        )


        async def main() -> None:
            response = await client.comment_automations.runs(
                id="cauto_01m4h40hg0f4wa1w5cfcgpjrp3",
            )
            async for item in response:
                yield item

            # alternatively, you can paginate page-by-page
            async for page in response.iter_pages():
                yield page


        asyncio.run(main())
        """
        return await self._raw_client.runs(
            id, status=status, cursor=cursor, limit=limit, request_options=request_options
        )

    async def test(
        self,
        id: str,
        *,
        text: str,
        idempotency_key: typing.Optional[str] = None,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> CommentAutomationTest:
        """
        Whether a comment with this text would trigger it, and the messages it would send, with their Rizamo links: each as its text and its button (the link, or the follow gate's reply button). Nothing is sent or recorded. Whether the person already got it, follows the account or is within Meta's windows is only known for real comments.

        Parameters
        ----------
        id : str
            The comment automation's id (`cauto_`).

        text : str
            A sample comment.

        idempotency_key : typing.Optional[str]

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        CommentAutomationTest
            OK

        Examples
        --------
        import asyncio

        from rizamo import AsyncRizamo

        client = AsyncRizamo(
            api_key="YOUR_API_KEY",
        )


        async def main() -> None:
            await client.comment_automations.test(
                id="cauto_01m4h40hg0f4wa1w5cfcgpjrp3",
                text="Menu please!",
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.test(
            id, text=text, idempotency_key=idempotency_key, request_options=request_options
        )
        return _response.data
